const body = $input.first().json.body ?? $input.first().json;
const msg = String(body.chatInput || body.message || '').trim().slice(0, 1200);
const rawHist = Array.isArray(body.history) ? body.history : [];
const history = rawHist
  .filter(m => m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string')
  .slice(-4)
  .map(m => ({ role: m.role, content: m.content.trim().slice(0, 400) }))
  .filter(m => m.content.length > 0);
const badRe = /(ignore all previous|ignore previous instructions|system prompt|reveal your instructions|developer mode|dan mode|vorherigen anweisungen)/i;
const isBlocked = !msg || badRe.test(msg);
return [{
  json: {
    message: msg,
    history,
    sessionId: String(body.sessionId || 'anon'),
    isBlocked,
    ollamaBase: String(body.ollama_base || 'http://ollama:11434'),
    model: String(body.model || 'conrad-n8n-agent:4b'),
    qdrantUrl: String(body.qdrant_url || 'http://n8n-qdrant-1:6333'),
    collection: String(body.qdrant_collection || 'conrad_ki_knowledge')
  }
}];

const qResp = $input.first().json;
const orig = $('Injection Guard').first().json;
const hits = Array.isArray(qResp?.result) ? qResp.result : [];
const snippets = hits.map((h, i) => `[Quelle ${i+1}] ` + String(h?.payload?.content || h?.payload?.text || JSON.stringify(h?.payload || {})).slice(0, 450)).join('\n');
return [{
  json: {
    userMessage: orig.message,
    history: Array.isArray(orig.history) ? orig.history : [],
    ollamaBase: orig.ollamaBase,
    model: orig.model || 'conrad-n8n-agent:4b',
    ragHits: hits.length,
    ragContext: snippets || 'Keine passenden Qdrant-Dokumente gefunden. Verweise bei Detailfragen an https://buchung.conrad-ki.com/merlin/30min.'
  }
}];

