const resp = $input.first().json;
const ctx = $('RAG Context Builder').first().json;
const fallback = 'Entschuldigung, unser System hat gerade eine kurze Pause. Buchen Sie gerne direkt Ihren 30-Minuten-Termin unter https://buchung.conrad-ki.com/merlin/30min.';
const text = String(resp?.message?.content || resp?.choices?.[0]?.message?.content || '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
return [{ json: { reply: text || fallback, blocked: false, ragHits: Number(ctx?.ragHits || 0) } }];
